    this.busy = true;
    // The first ask carries no cursor when the page wants recent context or
    // has no cursor yet; the answer says where "now" is.
    const query = this.primed && this.cursor != null ? `after=${this.cursor}` : `recent=${this.cfg.recent}`;
    this.primed = true;
